CREATE TABLE r AS SELECT a,b,sum(c)OVER(ORDER BY a GROUPS BETWEEN 2 PRECEDING AND CURRENT ROW EXCLUDE CURRENT ROW) AS x1,sum(c)OVER(ORDER BY a GROUPS BETWEEN 2 PRECEDING AND CURRENT ROW) AS x2,sum(c)OVER(ORDER BY a,b GROUPS BETWEEN 2 PRECEDING AND CURRENT ROW EXCLUDE CURRENT ROW) AS x3,sum(c)OVER(ORDER BY a,b GROUPS BETWEEN 2 PRECEDING AND CURRENT ROW) AS x4 FROM t3;